    <section id="view-jobs" class="view" hidden><h1>History</h1><p id="history-help" class="muted small"></p><button id="history-refresh" class="secondary">Refresh</button><p id="photos-status" class="muted small" role="status"></p><div id="photos-list" class="photos-grid"></div><button id="photos-more" class="secondary" hidden>Load more</button></section>
